import React, { useState } from "react";
import { useEffect } from "react";
import { useParams } from "react-router-dom";
import {
  AllCategory,
  UpdateServices,
  getSubCategory,
  getVendorDetails,
  getVendorServices,
  vendorServiceStatus,
} from "../../httpServices/dashHttpService";
import Sidebar from "../Sidebar";
import Swal from "sweetalert2";
import ImageEdit from "../../CropImage/ImageEdit";
import CustomizationModal from "./CustomizationModal";

const Services = () => {
  const [vendorService, setVendorService] = useState();
  const [slide, setSlide] = useState("VM");
  const [sideBar, setSideBar] = useState();
  const [vendor, setVendor] = useState();
  const [dataToEdit, setDataToEdit] = useState(null);
  const [category, setCategory] = useState();
  const [selectedEnCategory, setSelectedEnCategory] = useState("");
  const [preprationTime, setPreprationTime] = useState();
  const [orderService, setOrderService] = useState();
  const [deliveryType, setDeliveryType] = useState({
    normalDelivery: false,
    truckDelivery: false,
    coldDelivery: false,
    pickUpOnly: false,
  });

  const [selectedArCategory, setSelectedArCategory] = useState("");
  const [selectedEnSubCategory, setSelectedEnSubCategory] = useState("");
  const [selectedArSubCategory, setSelectedArSubCategory] = useState("");
  const [subCategory, setSubCategory] = useState([]);
  const [modalVisible, setModalVisible] = useState(false);
  const [modalVisible2, setModalVisible2] = useState(false);
  const [croppedImage, setCroppedImage] = useState();
  const [croppedImageUrl, setCroppedImageUrl] = useState();

  const [serviceNameEn, setServiceNameEn] = useState();
  const [serviceNameAr, setServiceNameAr] = useState();
  const [descriptionNameEn, setDescriptionNameEn] = useState();
  const [descriptionNameAr, setDescriptionNameAr] = useState();
  const [price, setPrice] = useState();
  const [categoryId, setCategoryId] = useState();
  const [serviceImage, setServiceImage] = useState();

  const [subCat_Id, setSubCat_Id] = useState();

  console.log({ deliveryType });

  const [customizationModalVisible, setCustomizationModalVisible] =
    useState(false);

  const [customizationData, setCustomizationData] = useState({
    status: false,
    options: [],
    maxSelection: 1,
    isRequired: false,
  });

  const handleEditCustomization = (item) => {
    console.log({ item });

    if (item.packages?.length) {
      setCustomizationData(item);
    } else {
      setCustomizationData({
        status: false,
        options: [],
        isRequired: false,
        item: item,
        customized_option_title_ar: "",
        customized_option_title_en: "",
      });
    }
    setDataToEdit(item);
    setCustomizationModalVisible(true);
  };

  let id = useParams();
  // console.log(id);
  useEffect(() => {
    GetVendorServices();
    GetVendor();
    getAllCategory();
  }, [customizationModalVisible]);

  const GetVendor = async () => {
    const { data } = await getVendorDetails(id?.id, { status: "APPROVED" });
    setVendor(data?.results.vendor);
  };

  const GetVendorServices = async () => {
    const { data } = await getVendorServices(id?.id);
    // console.warn(data.results.services);
    let values = data.results.services;
    setVendorService(data?.results?.services);
  };
  const getAllCategory = async () => {
    const { data } = await AllCategory();
    setCategory(data?.results?.categories);
    // console.log(data?.results?.categories);
  };
  const getAllSubCategory = async (categoryId) => {
    // console.log(categoryId);
    const { data } = await getSubCategory({ categoryId });
    if (data?.results?.subCategories) {
      setSubCategory(data?.results?.subCategories);
      setSelectedArSubCategory(data?.results?.subCategories[0]?.name_ar || " ");
      setSubCat_Id(data?.results?.subCategories[0]?._id);
    } else {
      setSelectedArSubCategory();
      setSelectedEnSubCategory();
    }
  };
  const getBarClick = (val) => {
    // console.log(val);
    setSideBar(val);
  };

  const closeModal = () => {
    setDataToEdit(null);
    setModalVisible(false);
    window.location.reload(false);
  };

  const handleEdit = async (item) => {
    let categoryId = item?.category?._id;
    // console.log(categoryId);
    if (categoryId) {
      await getAllSubCategory(categoryId);
    } else {
      setSubCategory([]);
    }
    setModalVisible(true);
    setDataToEdit(item);
    setCategoryId(item?.category?._id);
    setServiceNameEn(item?.name_en);
    setServiceNameAr(item?.name_ar);
    setServiceImage(item?.images?.[item?.images?.length - 1]);
    setDescriptionNameAr(item?.description_ar);
    setDescriptionNameEn(item?.description_en);
    setPrice(item?.price);
    setPreprationTime(item?.preparationTime);
    setOrderService(item?.no_of_order_per_service);
    setSelectedEnCategory(item?.category?.name_en);
    setSelectedEnSubCategory(item?.subCategory?.name_en || "");
    setSelectedArSubCategory(item?.subCategory?.name_ar || "");
    setDeliveryType({
      normalDelivery: item?.normalDelivery,
      truckDelivery: item?.truckDelivery,
      coldDelivery: item?.coldDelivery,
      pickUpOnly: item?.pickUpOnly,
    });
  };

  const handleCategoryEnChange = (e) => {
    let value = e.target.value;
    setCategoryId(value);
    const selectedCategoryId = value;
    if (category && category.length > 0) {
      const selectedCategory = category.find(
        (cat) => cat?._id === selectedCategoryId
      );

      if (selectedCategory) {
        getAllSubCategory(selectedCategory._id);
        setSelectedArCategory(selectedCategory.name_ar);
        setSelectedEnCategory(selectedCategory?.name_en);
      } else {
        setSubCategory([]);
        setSelectedEnSubCategory();
        setSelectedArSubCategory();
      }
    }
  };

  const handleSubCatChange = (e) => {
    let value = e.target.value;
    setSelectedEnSubCategory(value);
    let selectedSubCategory = subCategory.find(
      (subCat) => subCat?.name_en === value
    );
    setSelectedArSubCategory(selectedSubCategory.name_ar || "");
    setSubCat_Id(selectedSubCategory?._id);
  };
  const changeVendorServiceStatus = async (id) => {
    const { data } = await vendorServiceStatus(id);
    GetVendorServices();
    Swal.fire({
      toast: true,
      position: "top-end",
      icon: "success",
      title: "Status changed successfully",
      showConfirmButton: false,
      timerProgressBar: true,
      timer: 3000,
    });
  };

  console.log({ croppedImage });

  const handleEditFinish = async (id, e) => {
    e.preventDefault();
    let category_id = category.find((cat) => categoryId === cat?._id);

    const formData = new FormData();
    formData.append("name_en", serviceNameEn);
    formData.append("name_ar", serviceNameAr);
    formData.append("description_en", descriptionNameEn);
    formData.append("description_ar", descriptionNameAr);
    formData.append("preparationTime", preprationTime);
    formData.append("no_of_order_per_service", orderService);

    formData.append("categoryId", category_id?._id);
    formData.append("subCategoryId", subCat_Id ? subCat_Id : "");
    formData.append("price", price);
    formData.append("images", croppedImage);
    formData.append("removeImage", [serviceImage]);
    formData.append(
      "normalDelivery",
      deliveryType.normalDelivery ? "TRUE" : "FALSE"
    );
    formData.append(
      "truckDelivery",
      deliveryType.truckDelivery ? "TRUE" : "FALSE"
    );
    formData.append(
      "coldDelivery",
      deliveryType.coldDelivery ? "TRUE" : "FALSE"
    );
    formData.append("pickUpOnly", deliveryType.pickUpOnly ? "TRUE" : "FALSE");

    let { data } = await UpdateServices(id, formData);
    if (!data.error) {
      Swal.fire({
        title: data.message,
        icon: "success",
        confirmButtonText: "Okay",
        confirmButtonColor: "#e25829",
      }).then(() => {
        window.location.reload(false);
      });
    }
    setModalVisible(false);
    GetVendorServices();
  };

  return (
    <div className={sideBar === "click" ? "expanded_main" : "admin_main"}>
      <Sidebar slide={slide} getBarClick={getBarClick} />
      <div className="admin_panel_data height_adjust">
        <div className="row service-management justify-content-center">
          <div className="col-12">
            <div className="row mx-0">
              <div className="col-12 design_outter_comman shadow mb-4 toggle_set">
                <div className="row comman_header justify-content-between">
                  <div className="col-auto">
                    <h2>Vendor Details</h2>
                  </div>
                </div>
                <div className="row">
                  <form className="row align-items-center justify-content-center form-design position-relative p-4 py-5">
                    <div className="col-5">
                      <div className="row adjust_margin">
                        <div className="form-group col-12 mb-2">
                          <div className="userinfor_box text-center">
                            <span className="user_imgg">
                              <img
                                src={
                                  vendor?.shop_cover_image
                                    ? vendor?.shop_cover_image
                                    : require("../../../assets/img/uploadImg.jfif")
                                }
                                alt=""
                              />
                            </span>
                            <strong>{vendor?.full_name}</strong>
                          </div>
                        </div>
                        {/* <div class="form-group col-12 text-center mb-0">
                                    <label class="mb-0 text-center" for="">Registration Date: 01/01/2022</label>
                                 </div> */}
                      </div>
                    </div>
                    <div className="col-5">
                      <div className="row">
                        <div className="form-group col-12">
                          <label htmlFor="">Mobile Number</label>
                          <input
                            type="text"
                            className="form-control"
                            defaultValue={vendor?.phone_number}
                            name="name"
                            id="name"
                          />
                        </div>
                        <div className="form-group col-12 mb-0">
                          <label htmlFor="">Email Id </label>
                          <input
                            type="text"
                            className="form-control"
                            defaultValue={vendor?.email}
                            name="name"
                            id="name"
                          />
                        </div>
                      </div>
                    </div>
                    <div className="col-auto" />
                  </form>
                </div>
              </div>
              <div className="col-12 design_outter_comman shadow">
                <div className="row comman_header justify-content-between">
                  <div className="col-auto">
                    <h2>Service Details</h2>
                  </div>
                </div>
                <div className="row mx-0 ">
                  {vendorService?.length ? (
                    <div className="col-12 px-4 pb-4 ">
                      {vendorService?.map((item, index) => (
                        <div
                          className="row booking_details_box mt-4 position-relative"
                          key={index}
                        >
                          <div
                            className="position-absolute top-0 text-end check_toggle pe-5"
                            key={item?._id}
                          >
                            <input
                              type="checkbox"
                              defaultChecked={item?.status}
                              name="check1"
                              id={item?._id}
                              className="d-none"
                              onClick={() => {
                                changeVendorServiceStatus(item?._id);
                              }}
                            />
                            <label htmlFor={item?._id}></label>
                          </div>
                          <div className="text-end position-absolute bottom-0 pb-2">
                            <div className="text-end position-absolute bottom-0 pb-2">
                              <button
                                className="comman_btn py-1 px-4 me-2"
                                onClick={() => handleEdit(item)}
                              >
                                Edit
                              </button>
                              {}
                              <button
                                className="comman_btn py-1 px-4"
                                onClick={() => handleEditCustomization(item)}
                              >
                                Edit Customization
                              </button>
                            </div>
                          </div>

                          <div className="col-6 py-1">
                            <div className="row mx-0">
                              <div className="col-6">
                                <strong className="booking_head">
                                  Image :
                                </strong>
                              </div>
                              <div className="col-6">
                                <span className="booking_head">
                                  <img
                                    style={{
                                      width: "32%",
                                      height: "4rem",
                                      borderRadius: "12px",
                                    }}
                                    src={
                                      item?.images?.[item?.images?.length - 1]
                                    }
                                  />
                                </span>
                              </div>
                            </div>
                          </div>
                          {console.log(croppedImage)}

                          <div className="col-6 py-1">
                            <div className="row mx-0">
                              <div className="col-6">
                                <strong className="booking_head">
                                  Service Name :
                                </strong>
                              </div>
                              <div className="col-6">
                                <span className="booking_head">
                                  {item?.name_en}
                                </span>
                              </div>
                            </div>
                          </div>
                          <div className="col-6 py-1">
                            <div className="row mx-0">
                              <div className="col-6">
                                <strong className="booking_head">
                                  Customization :
                                </strong>
                              </div>
                              <div className="col-6">
                                <span className="booking_head">
                                  {item?.customization ? "YES" : "NO"}
                                </span>
                              </div>
                            </div>
                          </div>
                          <div className="col-6 py-1">
                            <div className="row mx-0">
                              <div className="col-6">
                                <strong className="booking_head">
                                  Category :
                                </strong>
                              </div>
                              <div className="col-6">
                                <span className="booking_head">
                                  {item?.category?.name_en}
                                </span>
                              </div>
                            </div>
                          </div>

                          <div className="col-6 py-2">
                            <div className="row mx-0">
                              <div className="col-6">
                                <strong className="booking_head">
                                  Sub Category :
                                </strong>
                              </div>
                              <div className="col-6">
                                <span className="booking_head">
                                  {item?.subCategory?.name_en}
                                </span>
                              </div>
                            </div>
                          </div>
                          <div className="col-6 py-1">
                            <div className="row mx-0">
                              <div className="col-6">
                                <strong className="booking_head">SAR :</strong>
                              </div>
                              <div className="col-6">
                                <span className="booking_head">
                                  {item?.price}
                                </span>
                              </div>
                            </div>
                          </div>

                          <div className="col-6 py-1">
                            <div className="row mx-0">
                              <div className="col-6">
                                <strong className="booking_head">
                                  Price :
                                </strong>
                              </div>
                              <div className="col-6">
                                <span className="booking_head">
                                  {item?.price}
                                </span>
                              </div>
                            </div>
                          </div>

                          <div className="col-6 py-1">
                            <div className="row mx-0">
                              <div className="col-6">
                                <strong className="booking_head">
                                  Description :
                                </strong>
                              </div>
                              <div className="col-6">
                                <span className="booking_head">
                                  {item?.description_en}
                                </span>
                              </div>
                            </div>
                          </div>
                        </div>
                      ))}
                    </div>
                  ) : (
                    <div className="col-12 px-4 pb-4">
                      <h6 className="mt-4">NO SERIVICES FOUND.... </h6>
                    </div>
                  )}
                </div>
              </div>

              <div
                className={`modal modal-lg ${
                  modalVisible ? "show d-block" : "d-none"
                }`}
                tabIndex="-1"
                role="dialog"
                aria-hidden="true"
              >
                <div className="modal-dialog">
                  <div className="modal-content">
                    <div className="modal-header">
                      <h5 className="modal-title">Edit Service Details</h5>
                      <button
                        type="button"
                        className="close close_btn"
                        onClick={closeModal}
                      >
                        <span aria-hidden="true">
                          <i class="fa-solid fa-xmark"></i>
                        </span>
                      </button>
                    </div>
                    <hr className="m-0" />
                    <div className="modal-body">
                      <form
                        className="form-design px-3 py-2 help-support-form row  justify-content-center"
                        action=""
                      >
                        <div className="form-group col-6">
                          <label htmlFor="">Service Name(En)</label>
                          <input
                            type="text"
                            className="form-control"
                            name="serviceName_en"
                            value={serviceNameEn}
                            onChange={(e) => setServiceNameEn(e.target.value)}
                          />
                        </div>

                        <div className="form-group col-6">
                          <label htmlFor="">Service Name(Ar)</label>
                          <input
                            type="text"
                            className="form-control"
                            name="serviceName_ar"
                            value={serviceNameAr}
                            onChange={(e) => setServiceNameAr(e.target.value)}
                          />
                        </div>

                        <div className="form-group col-12">
                          <label htmlFor="">Description(En)</label>
                          <input
                            type="text"
                            className="form-control"
                            name="description_en"
                            value={descriptionNameEn}
                            onChange={(e) =>
                              setDescriptionNameEn(e.target.value)
                            }
                          />
                        </div>
                        <div className="form-group col-12">
                          <label htmlFor="">Description(Ar)</label>
                          <input
                            type="text"
                            className="form-control"
                            name="description_ar"
                            value={descriptionNameAr}
                            onChange={(e) =>
                              setDescriptionNameAr(e.target.value)
                            }
                          />
                        </div>

                        <div className="form-group col-6">
                          <label htmlFor="">Prepration Time</label>
                          <input
                            type="number"
                            className="form-control"
                            name="preparationTime"
                            value={preprationTime}
                            onChange={(e) => setPreprationTime(e.target.value)}
                          />
                        </div>
                        <div className="form-group col-6">
                          <label htmlFor="">Orders/Service</label>
                          <input
                            type="number"
                            placeholder="Enter Number of Orders"
                            className="form-control"
                            name="orderService"
                            value={orderService}
                            onChange={(e) => setOrderService(e.target.value)}
                          />
                        </div>

                        <div className="form-group col-6">
                          <label htmlFor="">Select Category (En)</label>
                          <select
                            className="form-control w-100"
                            name="category_en"
                            id="category_en"
                            onChange={handleCategoryEnChange}
                          >
                            <option value={dataToEdit?.category?._id}>
                              {dataToEdit?.category?.name_en}
                            </option>
                            {category &&
                              category
                                .filter((cat) => cat.status === true)
                                .map((cat, i) => (
                                  <option value={cat?._id}>
                                    {cat.name_en}
                                  </option>
                                ))}
                          </select>
                        </div>
                        <div className="form-group col-6">
                          <label htmlFor="">Category (Ar)</label>
                          <input
                            type="text"
                            className="form-control"
                            name="category_ar"
                            value={
                              selectedArCategory
                                ? selectedArCategory
                                : dataToEdit?.category?.name_ar
                            }
                            disabled
                          />
                        </div>

                        {subCategory.length > 0 && (
                          <>
                            <div className="form-group col-6">
                              <label htmlFor="">Select Sub Category (En)</label>
                              <select
                                className="form-control w-100"
                                name=""
                                id="subCategory_en"
                                value={selectedEnSubCategory}
                                onChange={(e) => handleSubCatChange(e)}
                              >
                                {subCategory &&
                                  subCategory
                                    .filter((subCat) => subCat.status === true)
                                    .map((cat, i) => (
                                      <option value={cat.name_en}>
                                        {cat.name_en}
                                      </option>
                                    ))}
                              </select>
                            </div>
                            <div className="form-group col-6">
                              <label htmlFor="">Sub Category (Ar)</label>
                              <input
                                type="text"
                                className="form-control"
                                name="subCategory_ar"
                                // defaultValue={selectedArSubCategory}
                                value={selectedArSubCategory}
                                disabled
                              />
                            </div>
                          </>
                        )}
                        <div className="form-group col-6">
                          <label>Delivery Type</label>

                          <div className="form-check">
                            <input
                              type="checkbox"
                              className="form-check-input"
                              id="normalDelivery"
                              checked={deliveryType.normalDelivery}
                              onChange={() =>
                                setDeliveryType((prev) => ({
                                  ...prev,
                                  normalDelivery: !prev.normalDelivery,
                                }))
                              }
                            />
                            <label
                              className="form-check-label"
                              htmlFor="normalDelivery"
                            >
                              Normal Delivery
                            </label>
                          </div>

                          <div className="form-check">
                            <input
                              type="checkbox"
                              className="form-check-input"
                              id="truckDelivery"
                              checked={deliveryType.truckDelivery}
                              onChange={() =>
                                setDeliveryType((prev) => ({
                                  ...prev,
                                  truckDelivery: !prev.truckDelivery,
                                }))
                              }
                            />
                            <label
                              className="form-check-label"
                              htmlFor="truckDelivery"
                            >
                              Truck Delivery
                            </label>
                          </div>

                          <div className="form-check">
                            <input
                              type="checkbox"
                              className="form-check-input"
                              id="coldDelivery"
                              checked={deliveryType.coldDelivery}
                              onChange={() =>
                                setDeliveryType((prev) => ({
                                  ...prev,
                                  coldDelivery: !prev.coldDelivery,
                                }))
                              }
                            />
                            <label
                              className="form-check-label"
                              htmlFor="coldDelivery"
                            >
                              Cold Delivery
                            </label>
                          </div>

                          <div className="form-check">
                            <input
                              type="checkbox"
                              className="form-check-input"
                              id="pickUpOnly"
                              checked={deliveryType.pickUpOnly}
                              onChange={() =>
                                setDeliveryType((prev) => ({
                                  ...prev,
                                  pickUpOnly: !prev.pickUpOnly,
                                }))
                              }
                            />
                            <label
                              className="form-check-label"
                              htmlFor="pickUpOnly"
                            >
                              Pick Up Only
                            </label>
                          </div>
                        </div>

                        <div className="form-group col-6">
                          <label htmlFor="">Service Image</label>
                          <div
                            className="cursor-pointer position-relative"
                            onClick={() => {
                              setModalVisible2(true);
                            }}
                          >
                            <div>
                              <img
                                src={croppedImageUrl || serviceImage}
                                style={{
                                  width: "98%",
                                  height: "8rem",
                                  borderRadius: "12px",
                                }}
                                alt="image"
                                className="table_ismg"
                              />
                            </div>
                            <div
                              style={{
                                top: "-15px",
                                right: "-10px",
                                background: "#e25829",
                              }}
                              className="position-absolute rounded p-1"
                            >
                              <i
                                style={{
                                  left: "2px",
                                }}
                                className="fa fa-edit me-1 text-light position-relative"
                              />
                            </div>
                          </div>
                        </div>

                        <div className="form-group col-6">
                          <label htmlFor="">Price</label>
                          <input
                            type="text"
                            className="form-control"
                            name="price"
                            value={price}
                            onChange={(e) => setPrice(e.target.value)}
                          />
                        </div>
                      </form>
                    </div>
                    <div className="modal-footer">
                      <button
                        onClick={(e) => handleEditFinish(dataToEdit?._id, e)}
                        type="button"
                        className="comman_btn"
                      >
                        Update
                      </button>
                    </div>
                  </div>
                </div>
              </div>
            </div>
          </div>
        </div>
      </div>

      <div
        className={`modal modal-lg ${
          modalVisible2 ? "show d-block" : "d-none"
        }`}
        tabIndex="-1"
        role="dialog"
        aria-hidden="true"
      >
        <ImageEdit
          setModalVisible2={setModalVisible2}
          setCroppedImage={setCroppedImage}
          setCroppedImageUrl={setCroppedImageUrl}
        />
      </div>

      {/* Customization Modal */}
      <CustomizationModal
        visible={customizationModalVisible}
        onClose={() => setCustomizationModalVisible(false)}
        onSave={(updatedCustomizations) => {
          console.log(updatedCustomizations);
        }}
        initialData={customizationData}
      />
    </div>
  );
};

export default Services;
